#include <stdio.h>
#include <stdlib.h>

static int cmp_long_long(const void *a, const void *b) {
    long long x = *(const long long *)a;
    long long y = *(const long long *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int contains(long long *v, int n, long long key) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (v[mid] == key) return 1;
        if (v[mid] < key) lo = mid + 1;
        else hi = mid - 1;
    }
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *pos = (long long *)malloc(sizeof(long long) * n);
    long long sum = 0, total = 0;

    for (int i = 0; i < n; i++) {
        long long l;
        scanf("%lld", &l);
        pos[i] = sum;
        sum += l;
        total += l;
    }

    if (total % 2 != 0) {
        printf("N\n");
        free(pos);
        return 0;
    }

    qsort(pos, n, sizeof(long long), cmp_long_long);

    long long half = total / 2;
    int count = 0;

    for (int i = 0; i < n; i++) {
        long long target = pos[i] + half;
        if (target >= total) target -= total;
        if (contains(pos, n, target)) count++;
    }

    int pairs = count / 2;

    printf("%c\n", pairs >= 2 ? 'S' : 'N');

    free(pos);
    return 0;
}
